mapper.select:
SELECT t1.*,(select bt.description from hls_business_type bt where bt.business_type = t1.business_type and bt.document_category <> 'PRJ_PROJECT' and bt.document_category <> 'HLS_CREDIT_LINE') as business_type_n, ( SELECT rfc.description FROM AST_FIVE_CLASS_CODE rfc WHERE rfc.five_class_code = t1.five_class_code ) AS five_class_name, ( SELECT rfc.description FROM AST_FIVE_CLASS_CODE rfc WHERE rfc.five_class_code = t1.five_class_code_by_system ) AS five_class_name_by_system, ( SELECT rfc.description FROM AST_FIVE_CLASS_CODE rfc WHERE rfc.five_class_code = t1.original_five_class_code ) AS original_five_class_name, ( case when nvl(t1.original_five_class_code,1) <> nvl(t1.five_class_code_by_system,1) then '是' else '否' end)is_change_des FROM ( SELECT r.result_id, r.fc_estimate_id, t.contract_id, t.contract_number, t.contract_name, t.business_type, r.five_class_code, r.five_class_code_by_system, r.description, r.original_five_class_code, r.ref_v01, r.ref_v02, r.ref_v03, r.ref_v04, r.ref_v05, r.ref_n01, r.ref_n02, r.ref_n03, r.ref_n04, r.ref_n05, r.ref_d01, r.ref_d02, r.ref_d03, r.ref_d04, r.ref_d05, IFNULL ( r.STATUS, 'NEW' ) STATUS, r.estimate_date FROM CON_CONTRACT t, AST_FC_ESTIMATE_RESULT r WHERE t.data_class = 'NORMAL' AND t.contract_status ='INCEPT' AND t.contract_id = r.contract_id AND r.fc_estimate_id=#{map.fc_estimate_id}
and t.contract_number = #{map.contract_number}
and t.contract_name like concat('%',concat(#{map.contract_name},'%'))
) t1
t1.result_id = #{map.result_id}
AND t1.business_type = #{map.business_type}
AND ${map.estimate_date_t}
AND ${map.estimate_date_f}
AND (nvl(t1.original_five_class_code,1) <> nvl(t1.five_class_code_by_system,1))
AND (nvl(t1.original_five_class_code,1) = nvl(t1.five_class_code_by_system,1))
